/// asked between them, as libgit2's HTTP client asks `llhttp_should_keep_alive` at
/// `on_headers_complete`.
#[test]
#[cfg_attr(miri, ignore = "calls C")]
fn the_hooks_in_sequence_are_llhttps() {
    let messages = [
        (2, sys::F_CONTENT_LENGTH, 200, 1, (1, 1), 10),
        (2, sys::F_CHUNKED | sys::F_TRANSFER_ENCODING, 200, 1, (1, 1), 0),
        (2, sys::F_UPGRADE | sys::F_CONNECTION_UPGRADE, 101, 1, (1, 1), 0),
        (2, sys::F_CONNECTION_KEEP_ALIVE, 200, 1, (1, 0), 0),
        (1, 0, 0, 5, (1, 1), 0),
        (1, sys::F_UPGRADE | sys::F_CONNECTION_UPGRADE | sys::F_CONTENT_LENGTH, 0, 3, (1, 1), 2),
        (1, sys::F_TRANSFER_ENCODING, 0, 3, (1, 1), 0),
    ];
    let null = std::ptr::null();
    for (parser_type, flags, status_code, method, version, content_length) in messages {
        let state = State {
            parser_type,
            flags: u16::try_from(flags).unwrap(),
            status_code,
            method,
            version,
            content_length,
            finish: 1,
            ..State::default()
        };
        let mut c = state.parser();
        let mut rust = state.parser();
        let c_ptr = c.as_mut().as_mut_ptr();
        // SAFETY (each C call below): `c_ptr` addresses the live parser `c`, which nothing
        // else accesses during the call; the hooks do not read `p` and `endp`.
        let c_steps = [
            unsafe { llhttp__before_headers_complete(c_ptr, null, null) },
            unsafe { sys::llhttp_should_keep_alive(c_ptr) },
            unsafe { llhttp__after_headers_complete(c_ptr, null, null) },
            unsafe { sys::llhttp_message_needs_eof(c_ptr) },
            unsafe { llhttp__after_message_complete(c_ptr, null, null) },
            unsafe { sys::llhttp_should_keep_alive(c_ptr) },
        ];
        let mut r = rust.as_mut();
        r.before_headers_complete();
        let rust_steps = [
            0,
            c_int::from(r.as_ref().should_keep_alive()),
            code(r.as_ref().after_headers_complete()),
            c_int::from(r.as_ref().message_needs_eof()),
            c_int::from(r.after_message_complete()),
            c_int::from(r.as_ref().should_keep_alive()),
        ];
        assert_eq!(c_steps, rust_steps, "{state:?}");
        assert_eq!(fields(&c), fields(&rust), "{state:?}");
    }
}

