def flat(x,p=''):
    o={}
    if isinstance(x,dict):
        for k,v in x.items(): o.update(flat(v,p+'.'+k if p else k))
    else: o[p]=x
    return o
fb,ft=flat(b),flat(t)
for k in sorted(set(fb)|set(ft)):
    if fb.get(k)!=ft.get(k): print(k, fb.get(k), '->', ft.get(k))
